/* ================================================================
   qwform.js —— 工具工作台的「公式与术语」组件（2026-11-04 晚）
   ================================================================
   用户原话：「这些计算公式要写出来，每个专业名词要解释清楚」

   ---- 要解决什么 ----
   之前的工具页只给结论，不给依据：
     · SPC 图上写着 UCL / CL / LCL / σ，但这些数怎么算出来的没写；
     · 「失控信号 14 处」—— 哪 14 条规则、为什么这样判；
     · 「组间差距 5.6 (pp)」—— pp 是什么，和 % 差在哪；
     · 「加速因子 Q10 = 2.0×」—— Q10 哪来的；
     · 「Fisher 布局」—— 术语一个都没解释。
   → 用的人不一定是食品专业出身（更别说质量工程师），
     看到这些数字没法判断对不对，也没法向别人解释。

   ---- 本文件提供 ----
     QWForm.box(opt)          生成一个「公式与术语」折叠面板
       opt = {
         title,               面板标题（默认「计算公式与术语说明」）
         formulas: [{name, expr, note, vars:[{k,v}]}],
         terms:    [{k, name, desc}],
         open                  初始是否展开（默认 false）
       }
     QWForm.term(k)           取单个术语的解释（给 title 悬停用）
     QWForm.tip(k, label)     生成带悬停解释的 HTML（内联在正文里）
     QWForm.DICT              全部术语的字典（按工具分组）

   ---- 设计原则 ----
   ★ 公式用「符号 + 文字」两行写，不用图片、不用 LaTeX ——
     浏览器原生就能看、能选中、能复制进 Word。
   ★ 每个符号都要有解释：CL = Σxᵢ / n，这里 Σ 是什么、xᵢ 是什么都要写。
   ★ 术语表按工具分组，同一个词在不同工具里含义不同就分开写
     （比如「合格率」在层别里是按组算的，在通用表格里是按行算的）。
   ★ 面板默认收起 —— 一开始就把大段公式糊在脸上会吓退人，
     但必须**一眼能看见有个东西点得开**。
   ================================================================ */
(function (global) {
  "use strict";

  function esc(s) {
    /* ★ 不用 replace(/&/g,"&") 这种写法 ★
       HTML 实体在某些写入通道里会被解码掉（& → &），
       导致语法错误。用 split/join 拼，源码里没有实体就不会被解码。 */
    return String(s == null ? "" : s)
      .split("&").join("&" + "amp;")
      .split("<").join("&" + "lt;")
      .split(">").join("&" + "gt;")
      .split('"').join("&" + "quot;")
      .split("'").join("&" + "#39;");
  }

  /* ================================================================
     术语字典
     ================================================================
     key 用「工具类型.词条」，避免不同工具的同名词互相覆盖。
     desc 要说清楚「是什么 + 为什么这么定 + 怎么用」。
     ================================================================ */
  var DICT = {
    /* ---------------- SPC 控制图 ---------------- */
    "spc.CL":       { name: "CL 中心线", desc: "Center Line。全部数据点的算术平均值那条线，代表过程的「常态水平」。CL 本身漂移（整体偏高或偏低）说明过程中心发生了移动。计算式：CL = Σxᵢ / n。" },
    "spc.sigma":    { name: "σ 标准差", desc: "Sigma。衡量数据波动大小的统计量 —— σ 越大说明过程越不稳定、越容易出不合格品。这里用样本标准差（除以 n−1 而不是 n），因为我们只有一小批数据，想尽量准确地估计总体的波动。计算式：σ = √[Σ(xᵢ − CL)² / (n−1)]。" },
    "spc.UCL":      { name: "UCL 控制上限", desc: "Upper Control Limit。由过程自身数据算出的上限：UCL = CL + 3σ。它不是产品的合格线，而是「过程如果受控，数据不会跑到的地方」。超出 UCL 说明过程可能出了系统性变化。" },
    "spc.LCL":      { name: "LCL 控制下限", desc: "Lower Control Limit。由过程自身数据算出的下限：LCL = CL − 3σ。低于 LCL 同样是失控信号。若 LCL 为负数，说明这批数据本身波动很小，可以取 0 作为下限。" },
    "spc.3sigma":   { name: "±3σ 原则", desc: "为什么是 3 倍标准差：假设数据服从正态分布，约 99.73% 的点会落在 CL ± 3σ 之内，落在外面的概率不到 0.3%。所以偶尔跑出一个点不奇怪，但连续出现就是问题。" },
    "spc.ooc":      { name: "失控（Out of Control）", desc: "过程原有的统计规律被打破。判据是出现了「特殊原因」（assignable cause），如换原料、换设备、调参数、有人改动。失控必须查明原因并处理，不能只当噪声放过。" },
    "spc.spec":     { name: "规格限（Specification Limit）", desc: "国家标准或内控文件规定的合格范围（图中橙色虚线），代表「客户能接受什么」。控制限来自过程自身数据，规格限来自外部要求 —— 两者来源完全不同，这是 SPC 最容易搞混的地方。" },
    "spc.internal": { name: "内控限", desc: "企业自己设的、比国标更严的内部管理限。内控限通常比规格限更靠近中心线，用来提前预警，避免等到超出国标才发现问题。" },
    "spc.rule1":    { name: "规则① 单点超控制限", desc: "有 1 个点跑到 UCL 之上或 LCL 之下。判据：xᵢ > CL + 3σ 或 xᵢ < CL − 3σ。含义：这个点几乎不可能是随机波动，是明确的变化信号。" },
    "spc.rule2":    { name: "规则② 连续 9 点在中心线同侧", desc: "连续 9 个点全部大于 CL（或全部小于 CL）。判据：xᵢ > CL 连续 9 次 或 xᵢ < CL 连续 9 次。含义：即使每个点都在控制限内，这种分布也几乎不可能偶然出现，说明过程中心已经漂了。" },
    "spc.rule3":    { name: "规则③ 连续 6 点递增或递减", desc: "连续 6 个点一路上升或一路下降。判据：xᵢ₊₁ > xᵢ 连续 6 次（递减同理）。含义：趋势性变化，往往是某个因素在持续起作用（温度慢慢升、设备慢慢磨损）。" },
    "spc.cp":       { name: "Cp 过程能力", desc: "Process Capability。工程估计：规格宽度 ÷ 过程波动宽度，Cp = (USL − LSL) / (6σ)。衡量「这个过程先天有没有能力做合格」，只反映潜在能力，不看实际做到了没有。" },
    "spc.cpk":      { name: "Cpk 过程能力指数", desc: "Cp 的修正版，还要看过程中心是否偏在规格正中间。实际生产更看 Cpk：过程中心越偏，Cpk 越低。行业惯例：Cpk ≥ 1.33 可接受，≥ 1.67 良好。" },
    "spc.sigmaIdx": { name: "σ 水平（Sigmal Level）", desc: "用「过程波动只占规格允差的百分之几」来评价能力。σ 水平 = 规格允差 / 6σ。数值越大能力越好：1.33 对应 Cp=1.0，1.67 对应 Cp=1.33。" },

    /* ---------------- 帕累托图 ---------------- */
    "pareto.pct":   { name: "占比%", desc: "某一项占总次数的百分比。计算式：占比% = 该项次数 ÷ 总次数 × 100%。" },
    "pareto.cum":   { name: "累计%", desc: "从第一项起逐项累加占比之和。哪一项的累计% 刚好跨过 80%，说明「到这一项为止」的问题就占了全部问题的八成 —— 这就是帕累托分析要回答的问题。" },
    "pareto.tier":  { name: "梯队 A/B/C", desc: "按累计占比分组：A = 累计 ≤80%（关键少数，必须解决）；B = 80%~95%（次要问题，资源不够时往后放）；C = >95%（个别偶发问题，用常规管理即可）。" },
    "pareto.8020":  { name: "80/20 法则", desc: "帕累托原理的通俗说法：约 20% 的原因造成约 80% 的问题。它是经验规律不是定律，但用来排优先级非常有效 —— 先解决 A 梯队，其余的先不管。" },
    "pareto.vital": { name: "关键少数 / 次要多数", desc: "Vital Few（关键少数）指 A 梯队的少数项目；Trivial Many（次要多数）指 B、C 梯队的大量小问题。管理精力要压在关键少数上。" },

    /* ---------------- 直方图 ---------------- */
    "pareto.hist":  { name: "直方图", desc: "把数据按区间分堆，看分布形状。横轴是测量值区间，纵轴是落入该区间的个数。重点不是记数，而是看**形状**：双峰、偏峰、截尾各自指向不同的问题。" },
    "pareto.group": { name: "组数", desc: "分几堆。经验公式：组数 = √n（数据量 n），然后限制在 5~12 组之间。太少看不出形状，太多每堆只有一两个点、噪声很大。" },
    "pareto.binw":  { name: "组距", desc: "每一堆的区间宽度。计算式：组距 = (最大值 − 最小值) ÷ 组数。组距太大会掩盖细节，太小会把一个峰拆成几个假峰。" },
    "pareto.bimod": { name: "双峰", desc: "出现两个明显的峰。几乎总是意味着「两批东西混在一起」：两台设备、两个班次、两种原料、或者批间混料。先把两批分开，各自看分布是否正常。" },
    "pareto.skew":  { name: "偏峰", desc: "数据集中在一侧。说明过程中心相对规格有偏移 —— 大概率是某个设定值偏了，或者有一小部分数据被特殊因素影响。" },
    "pareto.trunc": { name: "截尾", desc: "两端突然断掉、样本很少或为零。通常意味着数据不是自然分布，而是被筛选过（只测了合格品）或存在测量限。" },
    "pareto.normal":{ name: "正态分布", desc: "钟形分布，中间多两头少。它是很多统计方法（包括 ±3σ 判异）成立的前提。如果直方图明显不像钟形，那些方法的结论就要打折扣。" },

    /* ---------------- 层别分析 ---------------- */
    "strata.rate":  { name: "合格率", desc: "该组里合格的比例。计算式：合格率 = 合格数 ÷ 样本数 × 100%。分层分析看的不是总合格率，而是**组与组之间**的合格率差距。" },
    "strata.pp":    { name: "pp（百分点）", desc: "Percentage Point，两个百分数直接相减的单位。例：合格率 92% 与 87%，差距是 5 个百分点（5 pp），不是 5%。相对变化才是百分比：92→87 是下降了 5.4%。差这一点，结论会完全反过来。" },
    "strata.gap":   { name: "组间差距", desc: "最好组与最差组的合格率之差。差距大说明这个分层维度能解释问题（存在「局部问题」）；差距小说明这个维度不是主因，换下一个维度拆。" },
    "strata.cross": { name: "交叉分层", desc: "在已有分层基础上再叠一层。比如先按班次分，发现夜班差；再在夜班内部按设备分，找出是哪台设备。维度要一个个叠，直到差距收敛。" },
    "strata.simu":  { name: "辛普森悖论", desc: "每一层单独看都好，合起来看却差（或反过来）。原因是不同时段/班次的产品构成比例不同。分层分析正是用来拆穿这种假象的。" },

    /* ---------------- 感官评价 ---------------- */
    "sensory.mean": { name: "均值", desc: "一个样品所有维度打分的算术平均值。计算式：x̄ = Σxᵢ / n。" },
    "sensory.sd":   { name: "标准差", desc: "反映评价员打分的离散程度。SD 越小说明大家意见越一致。计算式：s = √[Σ(xᵢ − x̄)² / (n−1)]。" },
    "sensory.range":{ name: "极差", desc: "所有样品均值中的最大值减最小值。极差大 = 不同样品确实吃起来不一样；极差小 = 要么真的差不多，要么评价员分辨不出（要靠描述性分析补）。" },
    "sensory.anchor":{ name: "锚定（Anchor）", desc: "用标样和竞品作为参照物固定评价员的判断尺度。缺少锚定，不同人心里对「香」的标尺不同，同一批样品的绝对分会漂移，跨批次数据就不可比。" },
    "sensory.abs":  { name: "绝对评价 / 描述性分析", desc: "绝对评价给样品的固定分数（好吃/不好吃）；描述性分析记录具体感受（偏甜、奶香不足、有哈味）。前者快、后者准，通常先绝对后描述补充。" },

    /* ---------------- 货架期 / 加速试验 ---------------- */
    "shelf.q10":    { name: "Q10 加速因子", desc: "温度每升高 10℃，化学反应速率约加快一倍。计算式：Q10 = 2^((T₂ − T₁) / 10)。所以 37℃ 的加速试验大致相当于 25℃ 的 4 倍时长。注意：这个「2 倍」是经验假设，不同产品差别很大。" },
    "shelf.indic":  { name: "指示性推算", desc: "用加速试验的数据折算回常温得到的保质期。它**只能当佐证，不能当依据** —— 因为加速条件下反应路径可能改变、包装吸氧、基质变了，结果会偏保守（短得离谱）。" },
    "shelf.retain": { name: "实时留样", desc: "在标示储存条件下（常温、避光、干燥）留样并定期检测。这是定保质期的**唯一合法依据**。加速试验做的是「快速发现问题」，实时留样做的是「证明没问题」。" },
    "shelf.85":     { name: "打 85 折", desc: "推算保质期 × 0.85 作为建议值。因为推到理论极限的那一天，产品状态通常已经不如刚到期时，留出余量给批次波动和运输条件。" },
    "shelf.vp":     { name: "过氧化值（VP）", desc: "反映油脂氧化酸败程度的指标。数值越高说明油脂越败。婴配粉国标要求过氧化值 ≤ 0.10 g/100g（另有酸价指标）。是货架期的关键监控项。" },

    /* ---------------- 原料替代测算 ---------------- */
    "sub.delta":    { name: "Δ（差值）", desc: "Δ = 替代后 − 现状。正数表示该营养素/成本增加，负数表示减少。Δ 不是「好坏」，还要看法规限量（钙铁锌等有上下限）、工艺可行性、口感影响。" },
    "sub.deltaPct": { name: "Δ%", desc: "成本变化的相对幅度。计算式：Δ% = Δ成本 ÷ 现状成本 × 100%。用百分比才能横向比较不同用量规模的原料。" },
    "sub.per100kg": { name: "每 1000kg 基准", desc: "所有计算都以 1000kg 产品为基准，便于把不同批次的用量折算到同一口径比较。" },
    "sub.stability":{ name: "稳定性影响", desc: "替代后营养素变了，配方体系的稳定性可能跟着变 —— 尤其是易氧化成分（脂质、维C、锌）和乳化体系。要重新做加速试验，不能只看营养表。" },

    /* ---------------- 5Why ---------------- */
    "why.deadend":  { name: "死胡同", desc: "答案里出现「人员不小心、疏忽、没注意到」这类说法时，分析就走进死胡同了 —— 因为人不可能被「要求更认真」这种措施改变。真正的根因通常是制度、设计、防错、流程上的缺失。" },
    "why.fixable": { name: "可整改项", desc: "答案指向能被改的东西：制度、流程、设备设计、防错、参数锁定、清单。没有落到可整改项，说明还没问到底。" },
    "why.spread":   { name: "横向展开", desc: "同样的原因在别处还有没有。例「除湿机没装」→ 要检查全厂三个粉料间是不是都没装。这一步能把一个点的问题变成一类问题。" },
    "why.evi":      { name: "证据 / 验证方式", desc: "每一层答案都要有事实依据（证据）和能验证它的方法（验证方式）。没有证据的答案只是猜测。" },

    /* ---------------- 鱼骨图 ---------------- */
    "fish.mmf":     { name: "人机料法环测（6M）", desc: "鱼骨图的六个分类：人（Man，操作/培训/疲劳）、机（Machine，设备/工装/维护）、料（Material，原料/包材/供应商）、法（Method，工艺/方法/标准）、环（Environment，温湿度/空间/交叉污染）、测（Measurement，仪器/方法/抽样）。分类是为了防止只盯着一个方向 —— 大多数问题出在「料」和「法」，但人往往先怪「机」。" },
    "fish.cand":    { name: "候选根因", desc: "图上用 ▶ 标红的条目。它们是**待验证的嫌疑对象**，不是结论。必须去现场确认：能不能观察到？测得到吗？验证过了才能定为根因。" },
    "fish.verify":  { name: "现场验证", desc: "对每条候选根因做一次能证伪的验证。比如怀疑「除湿机没装」→ 去现场看装没装、问保养记录。验不掉就划掉，不要都留着。"},
    "fish.4m1e":    { name: "4M1E", desc: "另一种常见分类法（人机料法＋环境），与 6M 的区别在于把「测量」单列。本页用 6M，多一个测量方向，因为实验室的抽样误差经常是问题根源。" },

    /* ---------------- 批次追溯 ---------------- */
    "trace.fwd":    { name: "正向追溯", desc: "从原料批号查出它进了哪些成品批（原料 → 成品）。用途：原料出问题时，算清楚要召回哪些成品。" },
    "trace.bwd":    { name: "反向追溯", desc: "从成品批号倒查出用了哪些原料/过程批（成品 → 原料）。用途：客户投诉时，快速定位问题来源批次。" },
    "trace.drill":  { name: "追溯演练", desc: "定期随机抽一个成品批号，要求在 2 小时内倒推全部原料批号。不演练等于没做追溯 —— 真出事时才会发现根本查不全。" },
    "trace.lot":    { name: "批号", desc: "生产批次的唯一标识。追溯的基本单位。批号规则要能反推生产日期和产线，且不能重复使用。" },

    /* ---------------- 通用表格 / 清单 ---------------- */
    "table.judge":  { name: "判定着色", desc: "表格里不合格的行自动标红、临界标黄，让问题一眼能挑出来，不靠人一行行读。" },
    "cl.rate":      { name: "符合率", desc: "已判定项中判定为符合的比例。计算式：符合数 ÷ 已判定数 × 100%。未判定的项不计入分母（否则会虚高）。" },
    "cl.open":      { name: "不符合项闭环", desc: "不符合项必须写清问题描述和整改要求，并且有验证关闭的记录。只登记不关闭，等于没发现问题。" },

    /* ---------------- 流程 / PDCA ---------------- */
    "flow.pdca":    { name: "PDCA", desc: "Plan 计划 → Do 执行 → Check 检查 → Act 改进，循环推进。关键在 Act：把这一轮的经验固化成标准，再进入下一轮。只 PD 不 A 就是白做。" },

    /* ---------------- 试剂 / 危化品 ---------------- */
    "lab.ghs":      { name: "GHS 象限", desc: "全球化学品统一分类和标签制度（GB 30000.1 是我国等同采用版本）。用图形化象限标识危险性：爆炸、易燃、氧化性、腐蚀、健康危害、环境危害等。替代了原 GB 13690 的分类。" }
  };

  /* ================================================================
     渲染
     ================================================================ */

  /* 公式一行：符号 | 表达式 | 说明 */
  function formulaRow(f, idx) {
    var varsHtml = "";
    if (f.vars && f.vars.length) {
      varsHtml = '<div class="qwf-vars">' + f.vars.map(function (v) {
        return '<span class="qwf-var"><b>' + esc(v.k) + '</b> = ' + esc(v.v) + '</span>';
      }).join("") + "</div>";
    }
    return '<div class="qwf-row">' +
      '<div class="qwf-name">' + esc(f.name || "") + "</div>" +
      '<div class="qwf-expr"><code>' + esc(f.expr || "") + "</code></div>" +
      (f.note ? '<div class="qwf-note">' + f.note + "</div>" : "") +
      varsHtml +
    "</div>";
  }

  /* 术语一行：词 | 解释 */
  function termRow(t) {
    return '<div class="qwt-term">' +
      '<div class="qwt-tk">' + esc(t.name || t.k) + "</div>" +
      '<div class="qwt-td">' + esc(t.desc || "") + "</div>" +
    "</div>";
  }

  /**
   * 生成「公式与术语」面板
   * opt = { title, formulas:[], terms:[], open:false }
   */
  function box(opt) {
    opt = opt || {};
    var fs = opt.formulas || [];
    var ts = opt.terms || [];
    if (!fs.length && !ts.length) return "";
    var id = "qwf_" + Math.random().toString(36).slice(2, 9);
    var h = '<details class="qwf-box"' + (opt.open ? " open" : "") + ' id="' + id + '">';
    h += '<summary class="qwf-sum">' +
      '<span class="qwf-ico">📐</span>' +
      '<b>' + esc(opt.title || "计算公式与术语说明") + "</b>" +
      (fs.length ? '<span class="qwf-badge">' + fs.length + " 个公式</span>" : "") +
      (ts.length ? '<span class="qwf-badge">' + ts.length + " 个术语</span>" : "") +
      '<span class="qwf-toggle">展开 ▾</span>' +
    "</summary>";
    h += '<div class="qwf-body">';
    if (fs.length) {
      h += '<div class="qwf-sec"><div class="qwf-sh">计算公式</div>' +
        fs.map(formulaRow).join("") + "</div>";
    }
    if (ts.length) {
      h += '<div class="qwf-sec"><div class="qwf-sh">术语解释</div>' +
        ts.map(termRow).join("") + "</div>";
    }
    h += "</div></details>";
    return h;
  }

  /* 取术语解释（给 title 悬停用） */
  function term(key) {
    var t = DICT[key];
    return t ? (t.name + "：" + t.desc) : "";
  }

  /* 生成带悬停解释的片段 */
  function tip(key, label) {
    var t = DICT[key];
    if (!t) return esc(label || "");
    return '<abbr class="qw-tip" title="' + esc(t.name + "：" + t.desc) + '">' +
      esc(label || t.name) + "</abbr>";
  }

  global.QWForm = {
    box: box,
    term: term,
    tip: tip,
    DICT: DICT
  };

})(window);
